-- Alerting (docs/backlog/phase-7.md, P7-03): rules over the route rollups, their evaluation
-- state, and a bounded history of notifications. Evaluated by src/alerts/evaluator.ts.

-- One row per rule. `secret` is the HMAC key of the rule's webhook signatures: generated by the
-- server, returned once by the API on create, never again. It is stored in clear because the
-- server must sign with it.
CREATE TABLE alert_rules (
  id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  name text NOT NULL CHECK (char_length(name) BETWEEN 1 AND 200),
  service_name text NOT NULL CHECK (char_length(service_name) BETWEEN 1 AND 256),
  -- NULL: every route of the service. Otherwise `route_minutes.route`, any method.
  route text CHECK (route IS NULL OR char_length(route) BETWEEN 1 AND 512),
  metric text NOT NULL CHECK (metric IN ('error_rate', 'p95_ms')),
  comparator text NOT NULL DEFAULT '>' CHECK (comparator = '>'),
  -- error_rate: a fraction (0.05 is 5%); p95_ms: milliseconds.
  threshold double precision NOT NULL,
  window_minutes integer NOT NULL CHECK (window_minutes BETWEEN 5 AND 60),
  -- How long the condition must hold before the rule fires (0: at the first breaching evaluation).
  for_minutes integer NOT NULL DEFAULT 2 CHECK (for_minutes BETWEEN 0 AND 60),
  -- Fewer requests than this in the window is "no data": the state does not change.
  min_requests integer NOT NULL DEFAULT 10 CHECK (min_requests BETWEEN 1 AND 1000000),
  webhook_url text NOT NULL CHECK (char_length(webhook_url) BETWEEN 1 AND 2048),
  secret text NOT NULL,
  enabled boolean NOT NULL DEFAULT true,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);

-- The evaluation state of each enabled rule; no row means `ok`. `pending` is a breach that has
-- not yet held for `for_minutes`. "Resolved" is a transition (firing -> ok), not a state.
CREATE TABLE alert_state (
  rule_id bigint PRIMARY KEY REFERENCES alert_rules (id) ON DELETE CASCADE,
  state text NOT NULL CHECK (state IN ('ok', 'pending', 'firing')),
  -- When the rule entered `state`.
  since timestamptz NOT NULL,
  -- The metric at the last evaluation; NULL when there was no data.
  last_value double precision,
  last_evaluated_at timestamptz NOT NULL,
  last_notified_at timestamptz
);

-- Notifications (firing, resolved, test) and how their delivery went. Rows older than
-- NESTRIX_RETENTION_DAYS are deleted by the evaluator.
CREATE TABLE alert_events (
  id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  rule_id bigint NOT NULL REFERENCES alert_rules (id) ON DELETE CASCADE,
  created_at timestamptz NOT NULL DEFAULT now(),
  kind text NOT NULL CHECK (kind IN ('firing', 'resolved', 'test')),
  value double precision,
  threshold double precision NOT NULL,
  -- pending: not delivered yet; sent: a 2xx answer; failed: no 2xx after every attempt;
  -- refused: never sent (address not allowed, bad URL).
  delivery text NOT NULL DEFAULT 'pending' CHECK (delivery IN ('pending', 'sent', 'failed', 'refused')),
  attempts integer NOT NULL DEFAULT 0,
  response_status integer,
  -- A short category (timeout, network, http_status, redirect, refused_address, ...), never a response body.
  error text
);

CREATE INDEX alert_events_created_idx ON alert_events (created_at);
CREATE INDEX alert_events_rule_idx ON alert_events (rule_id, id);
